/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent("dma_RegisterReq").get("transKind") == 0) {
        if ($c.util.getComponent("dma_RegisterReq").get("isuexerDdCheck") === $c.util.getComponent('cal_isuexerDd').getValue()&& $c.util.getComponent("dma_RegisterReq").get("isuexerRndCheck") === $c.util.getComponent('ipt_isuexerRnd').getValue()) {
            await $c.win.alert("발행일 또는 회차를 수정해야 신규작성 할 수 있습니다.");
            return;
        }
    }
    if (await scwin.vailidationLn() === false) {
        return;
    }
    scwin.setDataMergeDate();
    scwin.form.action = '/listInvstg/listPrelmInvstgEtc.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistRegEtc');
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteRegisterReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.deleteRegisterReq = async function () {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) {
        return;
    }
    if (($c.util.getComponent('cal_isuexerDd').getValue() == null ? '' : String($c.util.getComponent('cal_isuexerDd').getValue())) === '' || $c.util.getComponent('cal_isuexerDd').length == 0 || ($c.util.getComponent('ipt_isuexerRnd').getValue() == null ? '' : String($c.util.getComponent('ipt_isuexerRnd').getValue())) === '' || $c.util.getComponent('ipt_isuexerRnd').length == 0) {
        await $c.win.alert("삭제하시려면, 리스트에서  선택후 삭제하세요.");
        return;
    }
    $c.util.getComponent("dma_RegisterReq").set("transKind", 3);
    scwin.form.action = '/listInvstg/listPrelmInvstgEtc.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistRegEtc');
    await scwin.tx_fn_Delete();
    /* sdd-asis-lifecycle:end */
};


